Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1LA_0LA1RC_0RD0RC_1LD1LB (i r : nat) : LRule :=
  match i, r with
  | 0, 0 => iarm0_0_1RB1LA_0LA1RC_0RD0RC_1LD1LB
  | 0, 1 => iarm0_1_1RB1LA_0LA1RC_0RD0RC_1LD1LB
  | 1, 0 => iarm1_0_1RB1LA_0LA1RC_0RD0RC_1LD1LB
  | 1, 1 => iarm1_1_1RB1LA_0LA1RC_0RD0RC_1LD1LB
  | _, _ => iarm0_0_1RB1LA_0LA1RC_0RD0RC_1LD1LB   (* unreachable: i < 2 and r < N0i + sti *)
  end.

(** The fill arms, indexed by the WIDTH.  Both tails are known empty -- they
    are the only arms that see the end of the counter -- and the left-hand
    side is the top of the width, which here is a BARE run of [1]s.  That is
    both the largest MEMBER and the largest value ([fibsum k]), so unlike
    either other code it needs no fixed word at either end.  [fw1]/[fw2] say
    how the top's concrete copies of the run divide about the block and
    [fm1]/[fm2] the fill target's. *)
Definition farm_1RB1LA_0LA1RC_0RD0RC_1LD1LB (r : nat) : LRule :=
  match r with
  | 1 => farm1_1RB1LA_0LA1RC_0RD0RC_1LD1LB
  | _ => farm1_1RB1LA_0LA1RC_0RD0RC_1LD1LB   (* unreachable: 1 <= r < N0f + stf *)
  end.

Definition fw1_1RB1LA_0LA1RC_0RD0RC_1LD1LB (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.
Definition fw2_1RB1LA_0LA1RC_0RD0RC_1LD1LB (r : nat) : nat := match r with | 1 => 0 | _ => 0 end.
Definition fm1_1RB1LA_0LA1RC_0RD0RC_1LD1LB (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.
Definition fm2_1RB1LA_0LA1RC_0RD0RC_1LD1LB (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.

(** One chain per state per fill arm.  [vis_of_run] turns each into a visit
    and [topsF_cofinal] says the tops keep coming, which is all the liveness
    needs. *)
Definition vis_1RB1LA_0LA1RC_0RD0RC_1LD1LB (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 1;SCycL 1 0;SWinL 3]
  | 1, (StA, S1) => [SWin 1]
  | 1, (StB, S0) => []
  | 1, (StB, S1) => [SWin 1;SCycL 1 0;SWinL 4]
  | 1, (StC, S0) => [SWin 1;SCycL 1 0;SWin 2;SWinL 4;SCycR 1;SWin 1]
  | 1, (StC, S1) => [SWin 1;SCycL 1 0;SWinL 5]
  | 1, (StD, S1) => [SWin 1;SCycL 1 0;SWin 2;SWinL 4;SCycR 1;SWin 2]
  | _, _ => []
  end.

