(** The machine-level theorem, on the QUASIHALTING side
    ([LadderCheckFibTr.boardF_qhtr]). *)
Theorem qhtr_1RB1LA_0LA1RC_0RD0RC_1LD1LB :
  NonHalt tm_1RB1LA_0LA1RC_0RD0RC_1LD1LB /\ QHBoundTr 32779478 tm_1RB1LA_0LA1RC_0RD0RC_1LD1LB /\ QuasiHaltsTr tm_1RB1LA_0LA1RC_0RD0RC_1LD1LB.
Proof.
  eapply (boardF_qhtr tm_1RB1LA_0LA1RC_0RD0RC_1LD1LB pins_1RB1LA_0LA1RC_0RD0RC_1LD1LB FAM
                      iarm_1RB1LA_0LA1RC_0RD0RC_1LD1LB 1 1
