Definition karm_1RB1LD_1RC0RB_0LA1LA_0LD1RB (d e r : nat) : LRule :=
  match d, e, r with
  | 0, 0, 0 => karm0_0_0_1RB1LD_1RC0RB_0LA1LA_0LD1RB
  | 0, 1, 0 => karm0_1_0_1RB1LD_1RC0RB_0LA1LA_0LD1RB
  | 0, 0, 1 => karm0_0_1_1RB1LD_1RC0RB_0LA1LA_0LD1RB
  | 0, 1, 1 => karm0_1_1_1RB1LD_1RC0RB_0LA1LA_0LD1RB
  | _, _, _ => karm0_0_0_1RB1LD_1RC0RB_0LA1LA_0LD1RB
  end.

Definition earm_1RB1LD_1RC0RB_0LA1LA_0LD1RB (d r ph : nat) : LRule :=
  match d, r, ph with
  | 0, 0, 0 => earm0_0_0_1RB1LD_1RC0RB_0LA1LA_0LD1RB
  | 0, 1, 0 => earm0_1_0_1RB1LD_1RC0RB_0LA1LA_0LD1RB
  | _, _, _ => earm0_0_0_1RB1LD_1RC0RB_0LA1LA_0LD1RB
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB1LD_1RC0RB_0LA1LA_0LD1RB (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB1LD_1RC0RB_0LA1LA_0LD1RB
  | 2, 0 => farm2_0_1RB1LD_1RC0RB_0LA1LA_0LD1RB
  | 3, 0 => farm3_0_1RB1LD_1RC0RB_0LA1LA_0LD1RB
  | _, _ => farm1_0_1RB1LD_1RC0RB_0LA1LA_0LD1RB  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1LD_1RC0RB_0LA1LA_0LD1RB (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | 2, 0 => 1 | 3, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB1LD_1RC0RB_0LA1LA_0LD1RB (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 2, 0 => 1 | 3, 0 => 2 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB1LD_1RC0RB_0LA1LA_0LD1RB (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S1) => [SWinR 4]
  | 1, (StB, S0) => [SWinR 2]
  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => [SWinR 3]
  | 1, (StC, S1) => [SWinR 8]
  | 1, (StD, S0) => [SWinR 5]
  | 1, (StD, S1) => [SWin 0]
  | 2, (StA, S1) => [SWinR 5]
  | 2, (StB, S0) => [SWinR 3]
  | 2, (StB, S1) => [SWin 1]
  | 2, (StC, S0) => [SWinR 4]
  | 2, (StC, S1) => [SWinR 15]
  | 2, (StD, S0) => [SWinR 6]
  | 2, (StD, S1) => [SWin 0]
  | 3, (StA, S1) => [SWin 3;SCycR 1;SWinR 3]
  | 3, (StB, S0) => [SWin 3;SCycR 1;SWinR 1]
  | 3, (StB, S1) => [SWin 1]
  | 3, (StC, S0) => [SWin 3;SCycR 1;SWinR 2]
  | 3, (StC, S1) => [SWin 3;SCycR 1;SWinR 4;SCycL 1 0;SWin 15]
  | 3, (StD, S0) => [SWin 3;SCycR 1;SWinR 4]
  | 3, (StD, S1) => [SWin 0]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
    of a nested fill arm first runs that arm's program up to them. *)
Definition vsegs_1RB1LD_1RC0RB_0LA1LA_0LD1RB (r : nat) (t : Instr) : list nseg :=
  match r, t with
  | 1, (StA, S1) => []
  | 1, (StB, S0) => []
  | 1, (StB, S1) => []
  | 1, (StC, S0) => []
  | 1, (StC, S1) => []
  | 1, (StD, S0) => []
  | 1, (StD, S1) => []
  | 2, (StA, S1) => []
  | 2, (StB, S0) => []
  | 2, (StB, S1) => []
  | 2, (StC, S0) => []
  | 2, (StC, S1) => []
  | 2, (StD, S0) => []
  | 2, (StD, S1) => []
  | 3, (StA, S1) => []
  | 3, (StB, S0) => []
  | 3, (StB, S1) => []
  | 3, (StC, S0) => []
  | 3, (StC, S1) => []
  | 3, (StD, S0) => []
  | 3, (StD, S1) => []
  | _, _ => []
  end.

Lemma karm_reach_1RB1LD_1RC0RB_0LA1LA_0LD1RB : forall d e r,
  d < fm_b FAM - 1 -> e < fm_b FAM -> r < 1 + 1 ->
  ReachL tm (negb (fm_left FAM)) (fm_left FAM)
    (lr_lhs (karm_1RB1LD_1RC0RB_0LA1LA_0LD1RB d e r)) (lr_rhs (karm_1RB1LD_1RC0RB_0LA1LA_0LD1RB d e r)).
