      destruct r as [|r].
      { eapply narm_reach; [exact nrules_sound_1RB1LD_1RC0RB_0LA1LA_0LD1RB | exact ok_karm0_0_1_1RB1LD_1RC0RB_0LA1LA_0LD1RB]. }
      exfalso; lia.
    }
    destruct e as [|e].
    {
      destruct r as [|r].
      { eapply narm_reach; [exact nrules_sound_1RB1LD_1RC0RB_0LA1LA_0LD1RB | exact ok_karm0_1_0_1RB1LD_1RC0RB_0LA1LA_0LD1RB]. }
      destruct r as [|r].
